#!/usr/bin/env python3
# SRM15 inventory (machine-generated by grepping the SOURCES; run from the repo root: python3 scripts/srm15/inventory.py > scripts/srm15/INVENTORY.txt)
import re, subprocess
def grep(pat, files):
    out = []
    for f in files:
        for i, l in enumerate(open(f).read().split('\n'), 1):
            if re.search(pat, l): out.append(f'{f}:{i}: {l.strip()[:150]}')
    return out
G = 'Tools/ShippingSrm12Corr.lean'; T = 'Tests/Compiler/Srm12CorrTest.lean'
print('## (a) binders hgraph/hname/hnameK in the SRM12 generic theorems'); print('\n'.join(grep(r'\((hgraph|hname|hnameK) :', [G])))
print('\n## (b) where SRM12 instances supply them'); print('\n'.join(grep(r'gM_top_callees|gQ_top_callees|ifaceP .*\.name|ran_designCorr', [T])))
print('\n## (c) gM / gQ construction'); print('\n'.join(grep(r'noncomputable def g[MQ] ', ['Tests/Compiler/Srm7RankTest.lean'])))
print('\n## (d) source facts'); print('\n'.join(grep(r'^def callees|^abbrev (Kid|CallGraph)', ['Tools/ShippingSrm7Rank.lean']) + grep(r'structure ChildIfaceP|  name : b.name = nm', ['Tools/ShippingMemClosesKids.lean']) + grep(r'theorem kidTA_name|theorem (instTagged_mem_idx)', [G]) + grep(r'^def originAt', ['Tools/ShippingInstTagged.lean']) + grep(r'^def MachineDefines', ['Tools/ShippingMachineEntry.lean']) + grep(r'^structure MachineData', ['Tools/ShippingMachineAuto.lean'])))
print('\n## (e) duplicate check: SRM13/SRM14 branches touch (git diff --stat names only)')
for b in ['par/u-srm13', 'par/u-srm14']:
    names = subprocess.run(['git', 'diff', '--name-only', 'par/int-srm3', b], capture_output=True, text=True).stdout.split()
    print(b, ': graphOf/hgraph/hname occurrences in changed Lean files:',
          sum(1 for n in names if n.endswith('.lean') and re.search(r'graphOf|hgraph|hname', subprocess.run(['git', 'show', f'{b}:{n}'], capture_output=True, text=True).stdout)))
